package data

// The pantheon soul data PoB's src/Data/Pantheons.lua (`data.pantheons`) holds, derived from the game's
// PantheonPanelLayout as PoB's Export/Scripts/pantheons.lua derives it (scripts/gamedatadump pantheons).
//
// CODE GENERATED BY scripts/gopob pantheons-emit FROM 2.67.2-fixture. DO NOT EDIT.
// Regenerate with `task data-regen -- --only pantheons` after a go-pob-data bump.
//
// The previous revision was a hand transcription of v2.18.1 with no emitter, which is how it
// came to carry 3.20's pantheon changes as drift: renamed capturable souls, two gods whose soul
// lists were REORDERED, a rewritten mod line ("Cannot be Frozen" -> "100% chance to Avoid being
// Frozen") and four missing keys.

// PantheonSoul mirrors one entry of a god's `souls` table. PoB stores each mod as
// `{ line = ..., value = ... }`; only `line` is ever read, so `value` is not carried over.
type PantheonSoul struct {
	Name string
	Mods []string
}

// Pantheon mirrors one god. Souls are in PoB's table order: index 0 is the base soul and the
// rest are the capturable upgrade souls.
//
// ⚠️ THE ORDER IS LOAD-BEARING, NOT COSMETIC. calculator/env.go:1340 labels every mod of the god
// with `Souls[0].Name`, so a whole god reads as one "Pantheon:Soul of X" source regardless of
// which soul supplied the mod.
type Pantheon struct {
	Souls      []PantheonSoul
	IsMajorGod bool
}

// Pantheons is keyed exactly as PoB keys it, which is also the value stored in the build XML's
// pantheonMajorGod / pantheonMinorGod attributes.
//
// ⚠️ FOUR KEYS CARRY NO SOULS AT ALL — "Minor God 1", "2", "4" and "9" are `souls = {}` upstream.
// MEASURED against Data/Pantheons.lua:125-129, :130-134, :154-158 and :233-237, because the
// tempting reading is the opposite one and it was published here as fact: an earlier note in
// data/pob_data_drift_test.go called them "REAL entries, not placeholders — checked". They are
// placeholders. applySoulMod already returns early on a god with no souls, so carrying them
// changes nothing and closes the key-set finding honestly rather than by exclusion.

var Pantheons = map[string]Pantheon{
	"Minor God 1": {
		IsMajorGod: false,
		Souls:      nil,
	},
	"NoSoulsKey": {
		IsMajorGod: false,
		Souls:      nil,
	},
	"TheBrineKing": {
		IsMajorGod: true,
		Souls: []PantheonSoul{
			{
				Name: "Soul of the Brine King",
				Mods: []string{
					"You cannot be Stunned if you have been Stunned",
				},
			},
			{
				Name: "Soul of a Capturable",
			},
		},
	},
}
